/* 头像插画资源（生成物）：默认聊天对象与用户本人的内联头像。
   core/kit.js 的 avatar() 只接受 data:image/jpeg|png|webp;base64 内联图，故以 JPEG data URI 内嵌；
   图片由 AI 生成后压缩为 320×320 JPEG（与头像上传的 canvas 压缩规格一致，见 app.js avatar-input 处理）。
   键：p1 林间 / p2 陈一 / p3 小满 / self 当前用户；app.js 读取时用 `|| ''` 兜底，文件缺失不影响渲染。 */
window.LOVECO_AVATARS = {
  p1: "data:image/jpeg;base64,",
  p2: "data:image/jpeg;base64,",
  p3: "data:image/jpeg;base64,",
  self: "data:image/jpeg;base64,"
};
